package com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.builder;
import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.identity.StableId;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.ref.*;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.*;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.component.*;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.resource.*;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.skill.*;import java.util.ArrayList;import java.util.List;

/** Typed reducer support for the three P04 components and resource ClassOperation. */
final class ClassNodeDraftEditor{
	boolean supports(StableTarget value){return value instanceof BasicAttackComponentSpec||value instanceof ResourceFlowComponentSpec||value instanceof ActiveResourceOperationComponentSpec||value instanceof ResourceClassOperationSpec;}
	ClassBuildSpec setField(ClassBuildSpec build,String ownerId,String variant,String field,String raw){StableTarget target=BuilderDraftEditor.requireTarget(build,StableId.fromStored(ownerId));if(!supports(target)||!((ContractNodeSpec)target).variantKey().equals(variant))throw new IllegalArgumentException("P04 class node variant mismatch");ContractNodeSpec changed;
		if(target instanceof BasicAttackComponentSpec){BasicAttackComponentSpec x=(BasicAttackComponentSpec)target;changed=new BasicAttackComponentSpec(x.id(),x.displayName(),"availability".equals(field)?en(BasicAttackComponentSpec.BasicAttackAvailability.class,raw):x.availability(),"damage_numerator".equals(field)?integer(raw):x.damageNumerator(),"damage_denominator".equals(field)?integer(raw):x.damageDenominator(),x.allowedWeapons(),"action_time_turns".equals(field)?integer(raw):x.actionTimeTurns());}
		else if(target instanceof ResourceFlowComponentSpec){ResourceFlowComponentSpec x=(ResourceFlowComponentSpec)target;if("event_type".equals(field))changed=new ResourceFlowComponentSpec(x.id(),x.displayName(),new EventTriggerSpec(x.trigger().nodeId(),en(com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.runtime.GameplayEventContext.RuleEventType.class,raw)),x.condition(),x.operation());else changed=new ResourceFlowComponentSpec(x.id(),x.displayName(),x.trigger(),x.condition(),edit(x.operation(),strip(field),raw));}
		else if(target instanceof ActiveResourceOperationComponentSpec){ActiveResourceOperationComponentSpec x=(ActiveResourceOperationComponentSpec)target;if(field.startsWith("cost_"))changed=new ActiveResourceOperationComponentSpec(x.id(),x.displayName(),x.operationDisplayName(),x.classOperationId(),x.operation(),editCost(x.cost(),field,raw),x.actionTimeTurns());else changed=new ActiveResourceOperationComponentSpec(x.id(),x.displayName(),x.operationDisplayName(),x.classOperationId(),field.startsWith("operation_")||field.startsWith("operation.")||isOperationField(field)?edit(x.operation(),strip(field),raw):x.operation(),x.cost(),"action_time_turns".equals(field)?integer(raw):x.actionTimeTurns());}
		else{ResourceClassOperationSpec x=(ResourceClassOperationSpec)target;if(field.startsWith("cost_"))changed=new ResourceClassOperationSpec(x.id(),x.displayName(),x.sourceComponent(),x.activation(),x.condition(),editCost(x.cost(),field,raw),x.actionTimeTurns(),x.operation(),x.hudVisible(),x.hudOrder());else changed=new ResourceClassOperationSpec(x.id(),x.displayName(),x.sourceComponent(),x.activation(),x.condition(),x.cost(),"action_time_turns".equals(field)?integer(raw):x.actionTimeTurns(),field.startsWith("operation_")||field.startsWith("operation.")||isOperationField(field)?edit(x.operation(),strip(field),raw):x.operation(),"hud_visible".equals(field)?bool(raw):x.hudVisible(),"hud_order".equals(field)?integer(raw):x.hudOrder());}
		return replace(build,changed);
	}
	ClassBuildSpec setReference(ClassBuildSpec build,String ownerId,String variant,String field,TypedRef raw){StableTarget target=BuilderDraftEditor.requireTarget(build,StableId.fromStored(ownerId));StableTarget declaration=BuilderDraftEditor.requireTarget(build,raw.targetId());if(raw.kind()!=RefKind.RESOURCE||declaration.refKind()!=RefKind.RESOURCE)throw new IllegalArgumentException("resource reference required");ResourceRef ref=new ResourceRef(declaration.id(),declaration.displayName().fallback());ContractNodeSpec changed;if(target instanceof ResourceFlowComponentSpec){ResourceFlowComponentSpec x=(ResourceFlowComponentSpec)target;changed=new ResourceFlowComponentSpec(x.id(),x.displayName(),x.trigger(),x.condition(),rebind(x.operation(),strip(field),ref));}else if(target instanceof ActiveResourceOperationComponentSpec){ActiveResourceOperationComponentSpec x=(ActiveResourceOperationComponentSpec)target;if("cost.resource".equals(field)&&x.cost() instanceof ResourceCostSpec){ResourceCostSpec c=(ResourceCostSpec)x.cost();changed=new ActiveResourceOperationComponentSpec(x.id(),x.displayName(),x.operationDisplayName(),x.classOperationId(),x.operation(),new ResourceCostSpec(c.nodeId(),c.holder(),ref,c.amount()),x.actionTimeTurns());}else changed=new ActiveResourceOperationComponentSpec(x.id(),x.displayName(),x.operationDisplayName(),x.classOperationId(),rebind(x.operation(),strip(field),ref),x.cost(),x.actionTimeTurns());}else if(target instanceof ResourceClassOperationSpec){ResourceClassOperationSpec x=(ResourceClassOperationSpec)target;if("cost.resource".equals(field)&&x.cost() instanceof ResourceCostSpec){ResourceCostSpec c=(ResourceCostSpec)x.cost();changed=new ResourceClassOperationSpec(x.id(),x.displayName(),x.sourceComponent(),x.activation(),x.condition(),new ResourceCostSpec(c.nodeId(),c.holder(),ref,c.amount()),x.actionTimeTurns(),x.operation(),x.hudVisible(),x.hudOrder());}else changed=new ResourceClassOperationSpec(x.id(),x.displayName(),x.sourceComponent(),x.activation(),x.condition(),x.cost(),x.actionTimeTurns(),rebind(x.operation(),strip(field),ref),x.hudVisible(),x.hudOrder());}else throw new IllegalArgumentException("class node has no resource reference");return replace(build,changed);}
	private static CostSpec editCost(CostSpec cost,String field,String raw){if("cost_variant".equals(field)){if("NO_COST".equals(raw))return new NoCostSpec(cost.nodeId());if("HP".equals(raw))return HpCostSpec.safeDefault(cost.nodeId(),1);if("ACTION_TIME".equals(raw))return new ActionTimeCostSpec(cost.nodeId(),1);if("COOLDOWN".equals(raw))return new CooldownCostSpec(cost.nodeId(),1);if("RESOURCE".equals(raw))return new ResourceCostSpec(cost.nodeId(),ResourceHolderSelector.CLASS_OWNER,new ResourceRef(StableId.fromStored("unresolved_resource_cost"),""),1);throw new IllegalArgumentException("unsupported class operation cost "+raw);}int amount=integer(raw);if(cost instanceof ResourceCostSpec)return new ResourceCostSpec(cost.nodeId(),((ResourceCostSpec)cost).holder(),((ResourceCostSpec)cost).resource(),amount);if(cost instanceof HpCostSpec)return HpCostSpec.safeDefault(cost.nodeId(),amount);if(cost instanceof ActionTimeCostSpec)return new ActionTimeCostSpec(cost.nodeId(),amount);if(cost instanceof CooldownCostSpec)return new CooldownCostSpec(cost.nodeId(),amount);throw new IllegalArgumentException("cost amount does not apply");}
	private static ResourceOperationSpec edit(ResourceOperationSpec op,String field,String raw){if("variant".equals(field)){ResourceOperationSpec.Variant v=en(ResourceOperationSpec.Variant.class,raw);ResourceRef one=op.referencedResources().get(0),two=op.referencedResources().size()>1?op.referencedResources().get(1):new ResourceRef(StableId.fromStored("unresolved_resource_secondary"),"");return create(op.operationId(),v,one,two);}if(op instanceof GainResourceSpec){GainResourceSpec x=(GainResourceSpec)op;return new GainResourceSpec(x.operationId(),x.holder(),x.resource(),new FixedValueSpec(integer(raw)),x.overflowPolicy());}if(op instanceof DrainResourceSpec){DrainResourceSpec x=(DrainResourceSpec)op;return new DrainResourceSpec(x.operationId(),x.holder(),x.resource(),new FixedValueSpec(integer(raw)),x.insufficientPolicy());}if(op instanceof SetResourceSpec){SetResourceSpec x=(SetResourceSpec)op;return new SetResourceSpec(x.operationId(),x.holder(),x.resource(),new FixedValueSpec(integer(raw)));}if(op instanceof ClearResourceSpec)return op;if(op instanceof ConvertResourceSpec){ConvertResourceSpec x=(ConvertResourceSpec)op;return new ConvertResourceSpec(x.operationId(),x.holder(),x.source(),"source_amount".equals(field)?integer(raw):x.sourceAmount(),x.target(),"target_amount".equals(field)?integer(raw):x.targetAmount(),x.conversionPolicy(),x.targetOverflowPolicy());}if(op instanceof ReserveResourceSpec){ReserveResourceSpec x=(ReserveResourceSpec)op;return new ReserveResourceSpec(x.operationId(),x.holder(),x.resource(),"amount".equals(field)?integer(raw):x.amount(),"duration_turns".equals(field)?integer(raw):x.durationTurns(),x.expiryPolicy());}SuppressResourceSpec x=(SuppressResourceSpec)op;return new SuppressResourceSpec(x.operationId(),x.holder(),x.resource(),integer(raw),x.mode());}
	private static ResourceOperationSpec create(StableId id,ResourceOperationSpec.Variant v,ResourceRef one,ResourceRef two){switch(v){case GAIN:return new GainResourceSpec(id,ResourceHolderSelector.CLASS_OWNER,one,new FixedValueSpec(1),ResourceSpec.ResourceOverflowPolicy.FAIL);case DRAIN:return new DrainResourceSpec(id,ResourceHolderSelector.CLASS_OWNER,one,new FixedValueSpec(1),DrainResourceSpec.InsufficientResourcePolicy.FAIL);case SET:return new SetResourceSpec(id,ResourceHolderSelector.CLASS_OWNER,one,new FixedValueSpec(1));case CLEAR:return new ClearResourceSpec(id,ResourceHolderSelector.CLASS_OWNER,one);case CONVERT:return new ConvertResourceSpec(id,ResourceHolderSelector.CLASS_OWNER,one,1,two,1,ConvertResourceSpec.ConversionPolicy.EXACT_ATOMIC,ResourceSpec.ResourceOverflowPolicy.FAIL);case RESERVE:return new ReserveResourceSpec(id,ResourceHolderSelector.CLASS_OWNER,one,1,1,ReserveResourceSpec.ReservationExpiryPolicy.RETURN_TO_HOLDER);case SUPPRESS:return new SuppressResourceSpec(id,ResourceHolderSelector.CLASS_OWNER,one,1,SuppressResourceSpec.ResourceSuppressionMode.BLOCK_GAIN);default:throw new AssertionError(v);}}
	private static ResourceOperationSpec rebind(ResourceOperationSpec op,String field,ResourceRef ref){if(op instanceof ConvertResourceSpec){ConvertResourceSpec x=(ConvertResourceSpec)op;return new ConvertResourceSpec(x.operationId(),x.holder(),"source".equals(field)?ref:x.source(),x.sourceAmount(),"target".equals(field)?ref:x.target(),x.targetAmount(),x.conversionPolicy(),x.targetOverflowPolicy());}if(op instanceof GainResourceSpec){GainResourceSpec x=(GainResourceSpec)op;return new GainResourceSpec(x.operationId(),x.holder(),ref,x.amount(),x.overflowPolicy());}if(op instanceof DrainResourceSpec){DrainResourceSpec x=(DrainResourceSpec)op;return new DrainResourceSpec(x.operationId(),x.holder(),ref,x.amount(),x.insufficientPolicy());}if(op instanceof SetResourceSpec){SetResourceSpec x=(SetResourceSpec)op;return new SetResourceSpec(x.operationId(),x.holder(),ref,x.value());}if(op instanceof ClearResourceSpec){ClearResourceSpec x=(ClearResourceSpec)op;return new ClearResourceSpec(x.operationId(),x.holder(),ref);}if(op instanceof ReserveResourceSpec){ReserveResourceSpec x=(ReserveResourceSpec)op;return new ReserveResourceSpec(x.operationId(),x.holder(),ref,x.amount(),x.durationTurns(),x.expiryPolicy());}SuppressResourceSpec x=(SuppressResourceSpec)op;return new SuppressResourceSpec(x.operationId(),x.holder(),ref,x.durationTurns(),x.mode());}
	private static ClassBuildSpec replace(ClassBuildSpec build,ContractNodeSpec changed){ClassBuildSpec.Builder out=build.toBuilder();if(changed.nodeKind()==ContractNodeSpec.NodeKind.COMPONENT)out.classComponents(replaceList(build.classComponents(),changed));else out.classOperations(replaceList(build.classOperations(),changed));return out.build();}private static List<ContractNodeSpec> replaceList(List<ContractNodeSpec> values,ContractNodeSpec changed){List<ContractNodeSpec> out=new ArrayList<>();for(ContractNodeSpec x:values)out.add(x.id().equals(changed.id())?changed:x);return out;}
	private static String strip(String field){return field.startsWith("operation.")?field.substring(10):field.startsWith("operation_")?field.substring(10):field;}private static boolean isOperationField(String x){return "variant".equals(x)||"amount".equals(x)||"source_amount".equals(x)||"target_amount".equals(x)||"duration_turns".equals(x);}private static int integer(String x){try{return Integer.parseInt(x);}catch(NumberFormatException e){throw new IllegalArgumentException("integer required");}}private static boolean bool(String x){if("true".equals(x))return true;if("false".equals(x))return false;throw new IllegalArgumentException("boolean required");}private static<E extends Enum<E>>E en(Class<E> t,String x){return Enum.valueOf(t,x);}
}
